{
  "task_category": "triage_lighthouse_multisupport",
  "project_name": "01_SITE_MA_METHODE",
  "global_assessment_fr": "Le projet souffre d'un payload video excessif (11.44 MiB desktop, 3.13 MiB mobile) et d'un chemin critique bloquant (CSS/fonts) qui impacte fortement le LCP mobile (16.2s). Les assets statiques (textures, map projet) sont aussi surdimensionns. Les gains rapides sont sur la compression video, le lazy-loading des medias hors viewport, et l'optimisation du chemin critique.",
  "primary_actions": [
    {
      "action_key": "video_payload",
      "priority": 1,
      "description_fr": "Compresser les videos principales (storyboard et transition) avec un codec moderne (AV1/VP9) et adapter la resolution au support (1080p desktop, 720p mobile). Cibler une reduction de 50% du poids sans perte de qualite perceptible.",
      "impact": "LCP, payload",
      "verification": "Vrifier le poids des assets video aprs compression et le LCP via Lighthouse."
    },
    {
      "action_key": "lazy_loading_media",
      "priority": 2,
      "description_fr": "Implmenter le lazy-loading pour les videos et images hors viewport initial (ex: contact-transition, project-grid-map). Utiliser `loading=\"lazy\"` pour les images et un systme de preload conditionnel pour les videos.",
      "impact": "LCP, payload, mainthread_work",
      "verification": "Confirmer que les assets hors viewport ne sont pas chargs au premier rendu."
    },
    {
      "action_key": "critical_css_inline",
      "priority": 3,
      "description_fr": "Extraire et inliner le CSS critique pour le rendu initial (above-the-fold). Dplacer le chargement des polices (Inter/Sora) en asynchrone avec `font-display: swap`.",
      "impact": "render_blocking, LCP",
      "verification": "Vrifier la rduction du temps de blocage CSS/fonts via Lighthouse."
    },
    {
      "action_key": "texture_optimization",
      "priority": 4,
      "description_fr": "Optimiser les textures statiques (contact-cube-face.png, project-grid-map-20260614.png) avec un format moderne (WebP/AVIF) et une compression adaptative. Rduire la rsolution si possible sans perte de qualit visuelle.",
      "impact": "payload",
      "verification": "Vrifier le poids des assets images aprs optimisation."
    },
    {
      "action_key": "unused_code_removal",
      "priority": 5,
      "description_fr": "Nettoyer le CSS et JS inutiliss (91.6 KiB CSS, 39.3 KiB JS) via des outils comme PurgeCSS ou Rollup. Minifier les fichiers restants.",
      "impact": "payload, mainthread_work",
      "verification": "Vrifier la rduction du poids des assets CSS/JS et l'absence de rgressions visuelles."
    }
  ],
  "secondary_findings": [
    {
      "action_key": "video_caption",
      "priority": 6,
      "description_fr": "Ajouter des sous-titres (captions)  la video principale (`body > video#story-video`) pour respecter les critres d'accessibilit. Utiliser le format WebVTT.",
      "impact": "accessibility",
      "verification": "Vrifier la prsence des sous-titres via Lighthouse ou un test manuel."
    }
  ]
}
